import{ReviewEngine}from"./review-engine.js";const STORAGE_KEY="incredible-india-reviews";function loadAll(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||"[]")}catch{return[]}}function saveAll(e){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(e))}catch(e){console.error("Failed to persist reviews:",e)}}function getCurrentUserId(){try{const e=window.authLib?.getStoredAuthUser?.();return e?.uid||e?.email||"guest"}catch{return"guest"}}function starRow(e){return"★".repeat(Math.round(e))+"☆".repeat(5-Math.round(e))}function sentimentBadge(e){return"positive"===e?'<span class="review-badge review-badge--positive">🙂 Positive</span>':"negative"===e?'<span class="review-badge review-badge--negative">🙁 Negative</span>':'<span class="review-badge review-badge--neutral">😐 Neutral</span>'}export function initReviews(e,t){if(!e)throw new Error("initReviews: container element is required");if(!t)throw new Error("initReviews: destinationId is required");const r=new ReviewEngine({reviews:loadAll()});let n="helpful",i=null;function a(){saveAll(r.reviews)}return function s(){const l=r.getSummary(t),o=r.getAverageRating(t),u=r.getFiltered(t,{sortBy:n,minRating:i});e.innerHTML=`\n      <section class="reviews-widget" aria-label="Traveler reviews for ${escapeHtml(t)}">\n        <div class="reviews-summary" role="region" aria-label="Review summary" aria-live="polite">\n          <div class="reviews-summary__score">\n            <span class="reviews-summary__avg" aria-hidden="true">${o||"—"}</span>\n            <span class="reviews-summary__stars" role="img" aria-label="Average rating ${o||0} out of 5 stars">${starRow(o)}</span>\n            <span class="reviews-summary__count">${l.reviewCount} review${1===l.reviewCount?"":"s"}</span>\n          </div>\n          <p class="reviews-summary__ai-text">${l.text}</p>\n          ${l.highlights.length?`<p class="reviews-summary__highlights">👍 Frequently praised: ${l.highlights.join(", ")}</p>`:""}\n          ${l.concerns.length?`<p class="reviews-summary__concerns">⚠️ Common concerns: ${l.concerns.join(", ")}</p>`:""}\n        </div>\n\n        <form class="review-form" id="review-form-${t}" aria-label="Write a review">\n          <label for="rating-${t}">Your rating\n            <select id="rating-${t}" name="rating" required aria-required="true">\n              <option value="">Select a rating</option>\n              ${[5,4,3,2,1].map(e=>`<option value="${e}">${e} star${e>1?"s":""}</option>`).join("")}\n            </select>\n          </label>\n          <label for="text-${t}">Your review\n            <textarea id="text-${t}" name="text" rows="3" maxlength="1000" required aria-required="true" placeholder="Share your experience..."></textarea>\n          </label>\n          <button type="submit">Submit review</button>\n        </form>\n\n        <div class="reviews-controls">\n          <label for="sort-${t}">Sort by\n            <select id="sort-${t}" aria-label="Sort reviews by">\n              <option value="helpful">Most helpful</option>\n              <option value="recent">Most recent</option>\n              <option value="rating_high">Highest rated</option>\n              <option value="rating_low">Lowest rated</option>\n            </select>\n          </label>\n          <label for="minrating-${t}">Min rating\n            <select id="minrating-${t}" aria-label="Filter by minimum rating">\n              <option value="">Any</option>\n              ${[5,4,3,2,1].map(e=>`<option value="${e}">${e}+</option>`).join("")}\n            </select>\n          </label>\n        </div>\n\n        <ul class="reviews-list" aria-live="polite" aria-label="Reviews list">\n          ${u.map(e=>`\n            <li class="review-card" data-id="${e.id}">\n              <div class="review-card__header">\n                <strong>${escapeHtml(e.author)}</strong>\n                <span role="img" aria-label="${e.rating} out of 5 stars">${starRow(e.rating)}</span>\n                ${sentimentBadge(e.sentiment.label)}\n              </div>\n              <p class="review-card__text">${escapeHtml(e.text)}</p>\n              <button class="review-card__helpful" data-id="${e.id}" aria-pressed="${e.votedBy?.includes(getCurrentUserId())?"true":"false"}" aria-label="Mark this review as helpful, currently ${e.helpfulVotes||0} helpful votes">\n                👍 Helpful (${e.helpfulVotes||0})\n              </button>\n            </li>`).join("")||'<li class="reviews-empty">No reviews yet — be the first to share your experience.</li>'}\n        </ul>\n      </section>\n    `,e.querySelector(`#review-form-${t}`).addEventListener("submit",e=>{e.preventDefault();const n=e.target,i=Number(n.rating.value),l=n.text.value.trim();i&&l&&(r.addReview({destinationId:t,author:getCurrentUserId(),rating:i,text:l}),a(),s())}),e.querySelector(`#sort-${t}`).value=n,e.querySelector(`#sort-${t}`).addEventListener("change",e=>{n=e.target.value,s()}),e.querySelector(`#minrating-${t}`).addEventListener("change",e=>{i=e.target.value?Number(e.target.value):null,s()}),e.querySelectorAll(".review-card__helpful").forEach(e=>{e.addEventListener("click",()=>{r.voteHelpful(e.dataset.id,getCurrentUserId()),a(),s()})})}(),r}function escapeHtml(e){return String(e).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}